  ('2', NULL, 'First2', NULL, 'Last2', NULL, '555-0102', NULL, 'two@example.com', '0', 'Home', '1 Main St', NULL, 'Bothell', 'Washington', '98011', 'United States', NULL);
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 a customer without email or phone keeps a row (LEFT JOINs); unknown phone type; a store customer is d…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;

